// Literal port of the team's Casa3DSDK (module house/outbuildings). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installHouseOutbuildings(K: Kernel, shared: Shared): void {
  const { t, bx, cursor, floorColor } = K;
  const sh = (...a: any[]): any => K.sh(...a);
  // ===== R43: yard buildings (res.outbuildings: walk-in outbuilding) =====
  // room, walls (with the door gap), door, windows and items enter the plan lists the rest of the SDK already knows how to draw (doors/colliders/E, windows, ceiling, roof, light)
  const OUTBUILDING_USE = { guest_room: ['bedroom', 'bedroom', t('outbuilding.guest_room')], office: ['office', 'office', t('outbuilding.office')], storage: ['stockroom', 'stockroom', t('outbuilding.storage')], gourmet: ['living', 'gourmet', t('outbuilding.gourmet')] };
  function applyOutbuildings(r) {
    // the structure pack names a wall by its floor and its place in the list (wall_<floor>_<index>); the renderer finds the part of the structure by that id
    const counts = new Map();
    r = Object.assign({}, r, { utilities: r.utilities || {}, walls: r.walls.map(w => { const i = counts.get(w.floor) || 0; counts.set(w.floor, i + 1); return w.id ? w : Object.assign({}, w, { id: `wall_${w.floor}_${i}` }); }) });
    const E = (r.outbuildings || []).filter(e => e && e.walls && e.walls.length && e.interior && e.interior.length); if (!E.length) return r;
    const rooms = r.rooms.slice(), walls = r.walls.slice(), doors = r.doors.slice(), windows = r.windows.slice(), items = r.items.filter(m => m.type !== 'outbuilding');
    for (const e of E) {
      const ti = OUTBUILDING_USE[e.use] || OUTBUILDING_USE.gourmet, it = e.interior[0], cx = (it[0] + it[2]) / 2, cz = (it[1] + it[3]) / 2, pe = e.ceiling || 2.6;
      rooms.push({ id: e.id, type: ti[0], name: ti[2], floor: 0, u0: it[0], v0: it[1], u1: it[2], v1: it[3], parts: e.interior, link: null, ceiling: pe, outbuilding: true, color: { wall: 'wall_' + ti[1], floor: 'floor_' + ti[1] } });
      for (const w of e.walls) { const alongU = w.axis === 'u', L = alongU ? w.v0 : w.u0, below = L < (alongU ? cz : cx); walls.push({ floor: 0, axis: w.axis, u0: w.u0, v0: w.v0, u1: w.u1, v1: w.v1, thickness: w.thickness, sides: below ? ['outside', e.id] : [e.id, 'outside'], exterior: true, type: 'wall', h: w.h, outbuilding: e.id }); }
      for (const p of e.doors || []) { const alongU = p.axis === 'u', below = p.pos < (alongU ? cz : cx); doors.push({ id: p.id, floor: 0, u: p.u, v: p.v, axis: p.axis, pos: p.pos, at: p.at, width: p.width, a: below ? 'outside' : e.id, b: below ? e.id : 'outside', opensTo: e.id, exterior: true, side: p.side, leaves: 1, model: 'single', hinge: 'start', zones: [], blocked: false, outbuilding: e.id }); }
      for (const j of e.windows || []) windows.push({ id: j.id, floor: 0, u: j.u, v: j.v, axis: j.axis, pos: j.pos, at: j.at, width: j.width, y0: j.y0, y1: j.y1, room: e.id, side: j.side, outbuilding: e.id });
      (e.items || []).forEach((m, i) => items.push({ id: e.id + '.' + m.type + i, type: m.type, category: m.category, x: m.u, z: m.v, ry: m.ry || 0, w: m.w, d: m.d, h: m.h, y: 0.04, frontU: m.frontU, frontV: m.frontV, room: e.id, floor: 0, outdoor: false, aabb: m.aabb, color: 'wood' }));
      items.push({ id: e.id + '.ceiling_light', type: 'ceiling_light', category: 'ceiling_light', x: cx, z: cz, ry: 0, w: 0.35, d: 0.35, h: 0.1, y: pe - 0.1, room: e.id, floor: 0, outdoor: false, assembly: 'ceiling', color: 'metal', decor: true });
    }
    return Object.assign({}, r, { rooms, walls, doors, windows, items });
  }
  function outbuildings() { // floor slab (above the yard soil) and door threshold
    const E = (shared.ctx.r.outbuildings || []).filter(e => shared.ctx.roomById[e.id] && shared.ctx.roomById[e.id].outbuilding); shared.ctx.outbuildingList = E; if (!E.length) return;
    cursor.group = 'f0';
    for (const e of E) {
      const c = shared.ctx.roomById[e.id], col = floorColor(c);
      for (const [a, b, c2, d] of e.interior) bx('plaster', a - 0.075, 0, b - 0.075, c2 + 0.075, 0.04, d + 0.075, col);
      for (const p of e.doors || []) { const alongU = p.axis === 'u', th = e.thickness || 0.15; if (alongU) bx('plaster', p.at - p.width / 2, 0, p.pos - th / 2 - 0.12, p.at + p.width / 2, 0.03, p.pos + th / 2 + 0.12, sh(shared.ctx.colors.facade || 0xd8d0c0, 0.8)); else bx('plaster', p.pos - th / 2 - 0.12, 0, p.at - p.width / 2, p.pos + th / 2 + 0.12, 0.03, p.at + p.width / 2, sh(shared.ctx.colors.facade || 0xd8d0c0, 0.8)); }
    }
  }
  Object.assign(K, { OUTBUILDING_USE, applyOutbuildings, outbuildings });
}
